import numpy as np, cv2
f=np.load('source_pixels.npz')['rgb']
for i in range(0,41):
 im=f[i]
 hsv=cv2.cvtColor(im,cv2.COLOR_RGB2HSV)
 # green / yellow vivid
 m=((hsv[:,:,0]>=22)&(hsv[:,:,0]<=55)&(hsv[:,:,1]>70)&(hsv[:,:,2]>90)).astype('uint8')
 n,l,st,cen=cv2.connectedComponentsWithStats(m,8)
 cc=[]
 for j in range(1,n):
  x,y,w,h,a=st[j]
  if a>=2: cc.append((a,round(cen[j][0],1),round(cen[j][1],1),(x,y,w,h)))
 print(f'{i+1:2}',cc)
